-- CONTRÔLE RAPIDE (LECTURE SEULE, quelques millisecondes) — à lancer IMMÉDIATEMENT après chaque opération de la fenêtre de mise en production. Aucune écriture.
-- États attendus selon l'étape (acl_historiques = droits d'exécution de reception_create / reception_update / reception_delete) :
--   avant gel / après dégel : {postgres=X/postgres,service_role=X/postgres} pour les trois  → gel_actif = false
--   après gel               : {postgres=X/postgres}                                           → gel_actif = true
--   migration absente       : objets_migration = {fonctions 0, colonnes 0, tables 0, declencheurs 0}
--   migration appliquée     : {fonctions 10, colonnes 11, tables 2, declencheurs 7} ; nouvelles_fonctions_ecriture : service_role = true, anon = false, authenticated = false, public = false
-- cump : file en échec = 0, interrupteur actif = true, 10 déclencheurs CUMP ; commandes_clients_15min : l'activité réelle continue (jamais bloquée).
SELECT jsonb_build_object(
  'horodatage_utc', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  'acl_historiques', (SELECT jsonb_object_agg(p.oid::regprocedure::text, coalesce(p.proacl::text, 'NULL')) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('reception_create', 'reception_update', 'reception_delete')),
  'gel_actif', (NOT has_function_privilege('service_role', 'reception_create(text, date, text, boolean, jsonb, uuid)', 'EXECUTE') AND NOT has_function_privilege('service_role', 'reception_update(uuid, text, date, text, boolean, jsonb, uuid)', 'EXECUTE') AND NOT has_function_privilege('service_role', 'reception_delete(uuid)', 'EXECUTE')),
  'historiques_ouverts_a_un_autre_role', (SELECT count(*) FROM pg_proc p, pg_roles r WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('reception_create', 'reception_update', 'reception_delete') AND NOT r.rolsuper AND r.oid <> p.proowner AND r.rolname <> 'service_role' AND has_function_privilege(r.oid, p.oid, 'EXECUTE')),
  'objets_migration', jsonb_build_object(
    'fonctions', (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname IN ('reception_commande_enregistrer', 'reception_commande_annuler', 'shipment_item_quantite_modifier', 'shipment_reception_etat', 'shipment_reception_quantites', 'shipment_items_proteger', 'shipments_proteger', 'stock_receptions_proteger', 'stock_reception_items_proteger', 'achats_historique_proteger')),
    'colonnes', (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public' AND ((table_name = 'stock_receptions' AND column_name IN ('shipment_id', 'cle_idempotence', 'empreinte', 'bl_fournisseur', 'created_by', 'created_by_email', 'annulee_le', 'annulee_par', 'annulation_motif')) OR (table_name = 'stock_reception_items' AND column_name = 'shipment_item_id') OR (table_name = 'shipments' AND column_name = 'statut_avant_reception'))),
    'tables', (SELECT count(*) FROM pg_class WHERE relnamespace = 'public'::regnamespace AND relname IN ('stock_reception_items_annulees', 'shipment_item_quantites_historique')),
    'declencheurs', (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal AND tgrelid::regclass::text IN ('shipments', 'shipment_items', 'stock_receptions', 'stock_reception_items') AND tgname NOT LIKE 'trg\_cump\_%')),
  'nouvelles_fonctions_ecriture', (SELECT jsonb_agg(jsonb_build_object('f', p.oid::regprocedure::text, 'service_role', has_function_privilege('service_role', p.oid, 'EXECUTE'), 'anon', has_function_privilege('anon', p.oid, 'EXECUTE'), 'authenticated', has_function_privilege('authenticated', p.oid, 'EXECUTE'),
      'public', EXISTS (SELECT 1 FROM aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a WHERE a.grantee = 0 AND a.privilege_type = 'EXECUTE'))) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('reception_commande_enregistrer', 'reception_commande_annuler', 'shipment_item_quantite_modifier')),
  'autres_fonctions_critiques', (SELECT jsonb_object_agg(p.oid::regprocedure::text, has_function_privilege('service_role', p.oid, 'EXECUTE')) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('order_create_checked', 'order_mark_livree', 'product_adjust_stock', 'recalc_pump', 'cump_traiter_file', 'cump_enfiler')),
  'cump', jsonb_build_object('actif', (SELECT cump_auto_actif()), 'file', (SELECT jsonb_object_agg(statut, n) FROM (SELECT statut, count(*) n FROM cump_file GROUP BY 1) x), 'declencheurs', (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal AND tgname LIKE 'trg\_cump\_%')),
  'activite', jsonb_build_object('commandes_clients_15min', (SELECT count(*) FROM orders WHERE created_at > now() - interval '15 minutes'), 'receptions_15min', (SELECT count(*) FROM stock_receptions WHERE created_at > now() - interval '15 minutes'),
      'requetes_en_cours_receptions', (SELECT count(*) FROM pg_stat_activity WHERE datname = current_database() AND pid <> pg_backend_pid() AND state <> 'idle' AND query ~* '(stock_receptions|stock_reception_items|shipment_items|reception_create|reception_update|reception_delete)'),
      'transactions_ouvertes', (SELECT count(*) FROM pg_stat_activity WHERE datname = current_database() AND pid <> pg_backend_pid() AND state IN ('idle in transaction', 'idle in transaction (aborted)')))
) AS controle_rapide;
